window.kbPageData["views/entry/k-9c7a70955330edf5"] = {"key":"entry/k-9c7a70955330edf5","state":{"route":"entry/k-9c7a70955330edf5"},"node":{"id":"k-9c7a70955330edf5","mode":"k","title":"等时工作量与效率之比","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["同一用时内完成量之比等于恒定效率之比"],"qs":["江苏 2025 C类 行测#56"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"公开回忆版沿用“未进行”的表述。需核对正式试卷或命题说明是否限定两项实验在取数时都恰好完成整次，以及剩余次数是否计入正在进行的一次。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：海洋科学实验还有8次未进行，地球物理实验还有16次未进行","review":{"definition":"原题引文：海洋科学实验还有8次未进行，地球物理实验还有16次未进行","explanation":"若基础地质实验结束时，海洋科学和地球物理恰好分别完成32次和24次，两项实验的效率比就是4∶3。海洋科学做完40次时，地球物理恰好做完30次，还需10次，对应C。若“未进行”只数尚未开始的实验，海洋科学也可能正在做第32次，直接用32∶24就无法确定准确的效率比。","references":[{"source":"web-c724397a3a8ab268","location":"第11页，第56题题干","quote":"还有8次未进行"}],"evidence":"海洋科学实验还有8次未进行，地球物理实验还有16次未进行","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2025 C类 行测#56":{"paper":"江苏 2025 C类 行测","n":56,"mod":"数量关系","src":["ffc394a1c160f331ec57.pdf",12],"asrc":["d1de3b437151c05b769e.pdf",16],"card":"229c36af6c37478d829ff33a","links":[{"id":"k-9c7a70955330edf5","role":"解题依据","why":"单次时长固定时，可用共同用时内的完成次数之比确定两项实验的效率比。"}]}},"terms":{},"references":{"web-c724397a3a8ab268":{"name":"星光公考《2025年江苏省公务员录用考试〈行测〉真题（C卷-考生回忆版）》","url":"https://upload.xingguanggongkao.com/pdf/2025%E5%B9%B4%E6%B1%9F%E8%8B%8F%E7%9C%81%E5%85%AC%E5%8A%A1%E5%91%98%E5%BD%95%E7%94%A8%E8%80%83%E8%AF%95%E3%80%8A%E8%A1%8C%E6%B5%8B%E3%80%8B%E7%9C%9F%E9%A2%98%EF%BC%88C%E5%8D%B7-%E8%80%83%E7%94%9F%E5%9B%9E%E5%BF%86%E7%89%88%EF%BC%89.pdf?time=1756887598"}},"topics":[],"units":{"k-9c7a70955330edf5":[["江苏 2025 C类 行测#56"]]}};
